type CatalogResult = { id: string; officialCode: string | null; villageName: string; moo: string | null; province: string; district: string; subdistrict: string; sourceName: string | null; source: "DATABASE" | "BUILT_IN_DEMO"; village: { id: string; isActive: boolean } | null };
type VillageRow = { id: string; name: string; moo: string | null; slug: string; province: string | null; district: string | null; subdistrict: string | null; address: string | null; phone: string | null; email: string | null; website: string | null; description: string | null; isActive: boolean; sourceNote: string | null; catalogVillageId: string | null; counts: { memberships: number; houses: number; news: number } };
type FormValues = { mode: "catalog" | "manual"; catalogVillageId: string; catalogSource: "DATABASE" | "BUILT_IN_DEMO"; builtInCatalogId: string; name: string; moo: string; slug: string; province: string; district: string; subdistrict: string; address: string; phone: string; email: string; website: string; description: string; sourceNote: string; correctionReason: string };
type FieldErrors = Partial<Record<keyof FormValues, string>>;
type DialogState = { title: string; description: string; tone: "default" | "danger"; action: () => Promise<void> } | null;

// This page renders one village form at a time. Catalog slugs are display-only;
// the action also independently rebuilds them from the catalog record.
let catalogSlugLocked = false;

const emptyForm: FormValues = { mode: "catalog", catalogVillageId: "", catalogSource: "DATABASE", builtInCatalogId: "", name: "", moo: "", slug: "", province: "", district: "", subdistrict: "", address: "", phone: "", email: "", website: "", description: "", sourceNote: "", correctionReason: "" };
const options = (values: string[]) => values.map((value) => ({ value }));
const exact = (value: string, values: { value: string }[]) => values.some((item) => item.value === value.trim());
const displayValue = (value: string | null | undefined, fallback: string) => value?.trim() ? value : fallback;
const attentionLabels: Record<string, string> = { "pending-bindings": "คำขอผูกบ้านรอตรวจ", "open-issues": "ปัญหาที่ยังไม่ปิด", "pending-appointments": "นัดหมายรอดำเนินการ", "missing-headman": "ยังไม่มีผู้ใหญ่บ้าน" };

function Field({ label, name, value, placeholder, error, type = "text", onChange, readOnly = false }: { label: string; name: keyof FormValues; value: string; placeholder: string; error?: string; type?: string; onChange: (name: keyof FormValues, value: string) => void; readOnly?: boolean }) {
  const isCatalogSlug = name === "slug" && catalogSlugLocked;
  return <div><label htmlFor={name} className="mb-1 block text-sm font-medium text-slate-700">{label}</label><input id={name} name={name} type={type} value={value} readOnly={readOnly || isCatalogSlug} placeholder={placeholder} onChange={(event) => onChange(name, event.target.value)} className={`w-full rounded-lg border px-3 py-2 text-sm text-slate-900 placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-green-500 ${readOnly || isCatalogSlug ? "bg-slate-50" : "bg-white"} ${error ? "border-red-300 bg-red-50" : "border-slate-300"}`} />{error ? <p className="mt-1 text-xs text-red-600">{error}</p> : null}{isCatalogSlug ? <p className="mt-1 text-xs text-slate-500">Slug ของหมู่บ้านจากฐานข้อมูลอ้างอิงถูกสร้างจากรหัสหมู่บ้านและไม่สามารถแก้ไขได้</p> : null}</div>;
}

function TextareaField({ label, name, value, placeholder, error, onChange }: { label: string; name: keyof FormValues; value: string; placeholder: string; error?: string; onChange: (name: keyof FormValues, value: string) => void }) {
  return <div><label htmlFor={name} className="mb-1 block text-sm font-medium text-slate-700">{label}</label><textarea id={name} name={name} value={value} rows={3} placeholder={placeholder} onChange={(event) => onChange(name, event.target.value)} className={`w-full rounded-lg border px-3 py-2 text-sm text-slate-900 placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-green-500 ${error ? "border-red-300 bg-red-50" : "border-slate-300"}`} />{error ? <p className="mt-1 text-xs text-red-600">{error}</p> : null}</div>;
}

function LegacyCatalogPicker({ values, results, totalCount, query, loading, selected, onQueryChange, onSelect, onManual }: { values: FormValues; results: CatalogResult[]; totalCount: number; query: string; loading: boolean; selected: boolean; onQueryChange: (value: string) => void; onSelect: (item: CatalogResult) => void; onManual: () => void }) {
  const source = values.catalogSource;
  const hasArea = Boolean(values.province && values.district && values.subdistrict);
  return <section><h3 className="mb-1 text-sm font-semibold text-slate-900">รายชื่อหมู่บ้านใน ต.{values.subdistrict || "พื้นที่ที่เลือก"}</h3><p className="mb-3 text-xs text-slate-500">เลือกหมู่บ้านจากฐานข้อมูลอ้างอิง ระบบจะเติมชื่อและพื้นที่ให้อัตโนมัติ</p>{!hasArea ? <p className="rounded-lg border border-dashed border-slate-300 p-4 text-sm text-muted-foreground">เลือกจังหวัด อำเภอ และตำบลก่อน เพื่อดูรายชื่อหมู่บ้านในพื้นที่นี้</p> : <><div className="mb-3 rounded-lg bg-slate-50 p-3 text-sm text-slate-700"><p>พื้นที่ที่เลือก: ต.{values.subdistrict} · อ.{values.district} · จ.{values.province}</p><p className="mt-1 font-medium">พบ {totalCount} หมู่บ้านจาก{source === "BUILT_IN_DEMO" ? "ข้อมูลตัวอย่างในโปรเจกต์" : "ฐานข้อมูลอ้างอิง"}</p>{source === "BUILT_IN_DEMO" ? <p className="mt-2 text-xs text-amber-700">ข้อมูลนี้เป็นข้อมูลตัวอย่างที่ติดมากับโปรเจกต์ สำหรับสาธิตการเลือกหมู่บ้าน หากใช้งานจริงสามารถนำเข้าข้อมูล Village Catalog จากไฟล์ภายนอกได้</p> : null}</div><label htmlFor="catalog-village-search" className="mb-1 block text-sm font-medium text-slate-700">กรองรายชื่อหมู่บ้าน</label><input id="catalog-village-search" value={query} onChange={(event) => onQueryChange(event.target.value)} placeholder="พิมพ์ชื่อหมู่บ้าน เช่น เขาพระ" className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-green-500" />{loading ? <p className="mt-3 text-sm text-muted-foreground">กำลังโหลดรายชื่อหมู่บ้านในตำบลนี้...</p> : results.length ? <div className="mt-3 max-h-64 space-y-2 overflow-y-auto pr-1">{results.map((item) => item.village ? <div key={item.id} className="rounded-lg border border-slate-200 bg-slate-50 p-3"><div className="flex flex-col gap-2 sm:flex-row sm:items-start sm:justify-between"><div><p className="text-sm font-semibold text-slate-900">{item.villageName}{item.moo ? ` · หมู่ ${item.moo}` : ""}</p><p className="text-xs text-slate-500">ต.{item.subdistrict} · อ.{item.district} · จ.{item.province}{item.officialCode ? ` · รหัส ${item.officialCode}` : ""}</p></div><span className={`w-fit rounded-full px-2 py-1 text-xs font-medium ${item.village.isActive ? "bg-emerald-100 text-emerald-700" : "bg-slate-200 text-slate-700"}`}>{item.village.isActive ? "เปิดใช้งานแล้ว" : "มี Village แล้ว (ปิดใช้งาน)"}</span></div><Link href={`/superadmin/villages/${item.village.id}`} className="mt-2 inline-flex text-xs font-medium text-green-700 hover:underline">เปิดดูหมู่บ้าน</Link></div> : <button key={item.id} type="button" onClick={() => onSelect(item)} className="block w-full rounded-lg border border-slate-200 bg-white p-3 text-left hover:border-green-500 hover:bg-green-50 focus:outline-none focus:ring-2 focus:ring-green-500"><p className="text-sm font-semibold text-slate-900">{item.villageName}{item.moo ? ` · หมู่ ${item.moo}` : ""}</p><p className="text-xs text-slate-500">หมู่ {item.moo || "-"} · ต.{item.subdistrict} · อ.{item.district} · จ.{item.province}{item.officialCode ? ` · รหัส ${item.officialCode}` : ""}</p><span className="mt-2 inline-flex text-xs font-medium text-green-700">เลือกหมู่บ้านนี้</span></button>)}</div> : <div className="mt-3 rounded-lg border border-dashed border-slate-300 p-4"><p className="text-sm font-medium text-slate-700">{query.trim() ? `ไม่พบ “${query.trim()}” ในรายชื่อหมู่บ้านของตำบลนี้` : `ยังไม่มีข้อมูลหมู่บ้านใน ต.${values.subdistrict} อ.${values.district} จ.${values.province} จากฐานข้อมูลอ้างอิง`}</p><p className="mt-1 text-xs text-muted-foreground">{query.trim() ? "ลองลบคำค้นหาเพื่อดูรายชื่อหมู่บ้านทั้งหมด หรือชื่อในฐานข้อมูลอาจมีคำว่า “บ้าน” นำหน้า" : "อาจเกิดจากยังไม่ได้นำเข้าข้อมูลหมู่บ้านของพื้นที่นี้ หรือข้อมูลจากไฟล์อ้างอิงไม่ครอบคลุม"}</p>{query.trim() ? <button type="button" onClick={() => onQueryChange("")} className="mt-3 text-sm font-medium text-green-700 hover:underline">ดูทั้งหมดในตำบลนี้</button> : null}</div>}{selected ? <div className="mt-3 rounded-lg border border-green-200 bg-green-50 p-3"><p className="text-xs font-semibold text-green-800">หมู่บ้านที่เลือก</p><p className="mt-1 text-sm font-semibold text-slate-900">{values.name}{values.moo ? ` · หมู่ ${values.moo}` : ""}</p><p className="text-xs text-slate-600">ต.{values.subdistrict} · อ.{values.district} · จ.{values.province}</p><p className="mt-1 text-xs font-medium text-green-700">ที่มา: {values.catalogSource === "BUILT_IN_DEMO" ? "ข้อมูลตัวอย่างในโปรเจกต์" : "ฐานข้อมูลหมู่บ้านอ้างอิง"}</p></div> : null}<div className="mt-3 border-t border-slate-100 pt-3"><button type="button" onClick={onManual} className="text-sm font-medium text-amber-700 hover:underline">ไม่พบหมู่บ้านที่ต้องการหลังตรวจสอบรายชื่อทั้งหมดแล้ว? เพิ่มแบบ Manual</button></div></>}</section>;
}

function CatalogPicker({ values, results, totalCount, query, loading, selected, onQueryChange, onSelect, onManual }: { values: FormValues; results: CatalogResult[]; totalCount: number; query: string; loading: boolean; selected: boolean; onQueryChange: (value: string) => void; onSelect: (item: CatalogResult) => void; onManual: () => void }) {
  const hasArea = Boolean(values.province && values.district && values.subdistrict);
  const selectedItem = results.find((item) => item.id === values.catalogVillageId || item.id === values.builtInCatalogId);

  return <section>
    <h3 className="text-sm font-semibold text-slate-900">รายชื่อหมู่บ้านในพื้นที่ที่เลือก</h3>
    {!hasArea ? <p className="mt-3 rounded-lg border border-dashed border-slate-300 p-4 text-sm text-slate-500">เลือกจังหวัด อำเภอ และตำบลก่อน เพื่อดูรายชื่อหมู่บ้าน</p> : <>
      <div className="mt-3 flex flex-wrap items-center justify-between gap-2 rounded-lg bg-slate-50 p-3 text-sm text-slate-700"><span>ต.{values.subdistrict} · อ.{values.district} · จ.{values.province}</span><span className="font-medium">{totalCount} รายการ</span></div>
      <label htmlFor="catalog-village-search" className="mt-3 block text-sm font-medium text-slate-700">กรองรายชื่อหมู่บ้าน</label>
      <input id="catalog-village-search" value={query} onChange={(event) => onQueryChange(event.target.value)} placeholder="พิมพ์ชื่อหมู่บ้าน เช่น เขาพระ" className="mt-1 w-full rounded-xl border border-slate-300 bg-white px-3 py-2 text-sm transition focus-visible:border-green-600 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-green-600 focus-visible:ring-offset-2" />
      {loading ? <p className="mt-3 text-sm text-slate-500">กำลังโหลดรายชื่อหมู่บ้าน…</p> : null}
      {!loading && results.length ? <div className="mt-3 max-h-[45vh] space-y-2 overflow-y-auto p-2 sm:max-h-[420px]">
        {results.map((item) => {
          const isSelected = item.id === values.catalogVillageId || item.id === values.builtInCatalogId;

          return item.village ? <div key={item.id} className="rounded-lg border border-slate-200 bg-slate-50 p-3"><div className="flex flex-wrap items-start justify-between gap-2"><div><p className="text-sm font-semibold text-slate-900">{item.villageName}{item.moo ? ` · หมู่ ${item.moo}` : ""}</p><p className="mt-1 text-xs text-slate-500">ต.{item.subdistrict} · อ.{item.district} · จ.{item.province}</p></div><span className={`rounded-full px-2 py-1 text-xs font-medium ${item.village.isActive ? "bg-emerald-100 text-emerald-700" : "bg-slate-200 text-slate-700"}`}>{item.village.isActive ? "เปิดใช้งานแล้ว" : "มีหมู่บ้านนี้ในระบบแล้ว (ปิดใช้งาน)"}</span></div><Link href={`/superadmin/villages/${item.village.id}`} className="mt-3 inline-flex text-xs font-medium text-green-700 hover:underline">เปิดดูหมู่บ้าน</Link></div> : <button key={item.id} type="button" onClick={() => onSelect(item)} aria-pressed={isSelected} className={["block w-full rounded-lg border p-3 text-left transition focus-visible:outline-none", "hover:border-green-500 hover:bg-green-50", "focus-visible:border-green-600 focus-visible:shadow-[inset_0_0_0_2px_rgba(34,197,94,0.45)]", isSelected ? "border-green-600 bg-green-50 shadow-[inset_0_0_0_2px_rgba(34,197,94,0.35)]" : "border-slate-200 bg-white"].join(" ")}><div className="flex flex-wrap items-start justify-between gap-2"><div><p className="text-sm font-semibold text-slate-900">{item.villageName}{item.moo ? ` · หมู่ ${item.moo}` : ""}</p><p className="mt-1 text-xs text-slate-500">ต.{item.subdistrict} · อ.{item.district} · จ.{item.province}</p></div><span className={isSelected ? "rounded-full bg-green-100 px-2 py-1 text-xs font-medium text-green-700" : "rounded-full bg-amber-50 px-2 py-1 text-xs font-medium text-amber-700"}>{isSelected ? "เลือกแล้ว" : "ยังไม่ได้เปิดใช้งาน"}</span></div></button>;
        })}
      </div> : null}
      {!loading && !results.length ? <div className="mt-3 rounded-lg border border-dashed border-slate-300 p-4 text-sm text-slate-500">ไม่พบหมู่บ้านที่ตรงกับเงื่อนไข</div> : null}
      {selected ? <div className="mt-3 rounded-xl border border-green-200 bg-green-50 p-3 text-sm text-green-900"><p className="font-semibold">เลือกแล้ว: หมู่ {values.moo || "-"} บ้าน{values.name}</p><p className="mt-1 text-xs text-green-800">ต.{values.subdistrict} · อ.{values.district} · จ.{values.province}</p>{selectedItem?.officialCode ? <p className="mt-1 text-xs text-green-800">รหัสอ้างอิง: {selectedItem.officialCode}</p> : null}<p className="mt-1 break-all text-xs text-green-800">Slug: {values.slug}</p></div> : null}
      <button type="button" onClick={onManual} className="mt-3 text-sm font-medium text-amber-700 hover:underline">ไม่พบหมู่บ้านที่ต้องการ? เพิ่มแบบ Manual</button>
    </>}
  </section>;
}

function LegacyVillageFormModal({ formMode, title, geography, initialValues, statusLabel, pending, serverError, onClose, onSubmit }: { formMode: "create" | "edit"; title: string; geography: ThaiProvince[]; initialValues: FormValues; statusLabel: string; pending: boolean; serverError?: string; onClose: () => void; onSubmit: (values: FormValues) => Promise<void> }) {
  const [values, setValues] = useState(initialValues); const [errors, setErrors] = useState<FieldErrors>({}); const [catalogQuery, setCatalogQuery] = useState(initialValues.catalogVillageId ? initialValues.name : ""); const [catalogResults, setCatalogResults] = useState<CatalogResult[]>([]); const [catalogTotal, setCatalogTotal] = useState(0); const [catalogLoading, setCatalogLoading] = useState(false);
  const provinceOptions = useMemo(() => options(geography.map((item) => item.name)), [geography]); const province = geography.find((item) => item.name === values.province); const districtOptions = useMemo(() => options(province?.districts.map((item) => item.name) ?? []), [province]); const district = province?.districts.find((item) => item.name === values.district); const subdistrictOptions = useMemo(() => options(district?.subdistricts ?? []), [district]); const selectedCatalog = values.mode === "catalog" && Boolean(values.catalogVillageId || values.builtInCatalogId);
  useEffect(() => { if (values.mode !== "catalog" || !values.province || !values.district || !values.subdistrict) return; let cancelled = false; const timer = window.setTimeout(() => { setCatalogLoading(true); void searchVillageCatalogAction({ province: values.province, district: values.district, subdistrict: values.subdistrict, query: catalogQuery }).then((result) => { if (!cancelled) { setCatalogResults(result.items); setCatalogTotal(result.totalCount); setValues((current) => current.catalogSource === result.source ? current : { ...current, catalogSource: result.source }); } }).finally(() => { if (!cancelled) setCatalogLoading(false); }); }, 250); return () => { cancelled = true; window.clearTimeout(timer); }; }, [catalogQuery, values.district, values.mode, values.province, values.subdistrict]);
  const setField = (name: keyof FormValues, value: string) => { setValues((current) => ({ ...current, [name]: value })); setErrors((current) => ({ ...current, [name]: undefined })); };
  const changeProvince = (value: string) => { setCatalogQuery(""); setCatalogResults([]); setCatalogTotal(0); setValues((current) => ({ ...current, province: value, district: "", subdistrict: "", catalogVillageId: "", builtInCatalogId: "", name: current.mode === "catalog" ? "" : current.name, moo: current.mode === "catalog" ? "" : current.moo })); };
  const changeDistrict = (value: string) => { setCatalogQuery(""); setCatalogResults([]); setCatalogTotal(0); setValues((current) => ({ ...current, district: value, subdistrict: "", catalogVillageId: "", builtInCatalogId: "", name: current.mode === "catalog" ? "" : current.name, moo: current.mode === "catalog" ? "" : current.moo })); };
  const selectCatalog = (item: CatalogResult) => { if (item.village) return; const isSelected = item.id === values.catalogVillageId || item.id === values.builtInCatalogId; if (isSelected) { setValues((current) => ({ ...current, catalogVillageId: "", builtInCatalogId: "", name: "", moo: "", slug: "" })); setErrors({}); return; } setValues((current) => ({ ...current, mode: "catalog", catalogVillageId: item.source === "DATABASE" ? item.id : "", catalogSource: item.source, builtInCatalogId: item.source === "BUILT_IN_DEMO" ? item.id : "", name: item.villageName, moo: item.moo ?? "", slug: buildCatalogVillageSlug({ villageName: item.villageName, moo: item.moo, officialCode: item.officialCode, fallbackId: item.id }), province: item.province, district: item.district, subdistrict: item.subdistrict })); setErrors({}); };
  const switchManual = () => { setValues((current) => ({ ...current, mode: "manual", catalogVillageId: "", builtInCatalogId: "" })); setCatalogResults([]); setCatalogTotal(0); setCatalogQuery(""); };
  const validate = () => { const next: FieldErrors = {}; if (values.mode === "manual" && !values.slug.trim()) next.slug = "กรุณากรอก slug"; if (!exact(values.province, provinceOptions)) next.province = "กรุณาเลือกจากรายการที่ระบบแนะนำ"; if (!exact(values.district, districtOptions)) next.district = "กรุณาเลือกจากรายการที่ระบบแนะนำ"; if (!exact(values.subdistrict, subdistrictOptions)) next.subdistrict = "กรุณาเลือกจากรายการที่ระบบแนะนำ"; if (values.mode === "catalog" && !values.catalogVillageId && !values.builtInCatalogId) next.catalogVillageId = "กรุณาเลือกหมู่บ้านจากรายการ"; if (values.mode === "manual" && !values.name.trim()) next.name = "กรุณากรอกชื่อหมู่บ้าน"; if (values.mode === "manual" && !values.moo.trim()) next.moo = "กรุณาระบุหมู่ที่"; if (values.mode === "manual" && !values.sourceNote.trim()) next.sourceNote = "กรุณาระบุเหตุผลหรือที่มา"; setErrors(next); return Object.keys(next).length === 0; };
  const submit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (!pending && validate()) await onSubmit(values); };
  catalogSlugLocked = values.mode === "catalog";
  return <div className="fixed inset-0 z-[80] flex items-end justify-center bg-slate-950/50 p-0 sm:items-center sm:p-4" role="dialog" aria-modal="true"><div className="flex max-h-[92vh] w-full flex-col rounded-t-2xl bg-white shadow-2xl sm:max-w-4xl sm:rounded-2xl"><div className="flex items-center justify-between border-b border-slate-200 px-4 py-3 sm:px-6"><div><h2 className="text-lg font-semibold text-slate-900">{title}</h2>{serverError ? <p className="mt-1 text-sm text-red-600">{serverError}</p> : null}</div><button type="button" onClick={onClose} disabled={pending} aria-label="ปิด" className="rounded-full p-2 text-slate-500 hover:bg-slate-100"><X className="h-5 w-5" /></button></div><form onSubmit={submit} className="overflow-y-auto px-4 py-4 sm:px-6"><div className="space-y-6"><section><p className="mb-3 text-xs text-slate-500">1. เลือกพื้นที่  2. เลือกหมู่บ้านจากฐานข้อมูลอ้างอิง  3. กรอกข้อมูลเสริมและสร้างหมู่บ้าน</p><div className="grid grid-cols-1 gap-3 lg:grid-cols-3"><SuggestCombobox id={`${formMode}-province`} label="จังหวัด" value={values.province} options={provinceOptions} placeholder="เลือกจังหวัด" emptyMessage="ไม่พบข้อมูลใน GeoThai" error={errors.province} disabled={selectedCatalog} onChange={changeProvince} /><SuggestCombobox id={`${formMode}-district`} label="อำเภอ" value={values.district} options={districtOptions} placeholder={values.province ? "เลือกอำเภอ" : "เลือกจังหวัดก่อน"} emptyMessage="ไม่พบข้อมูลใน GeoThai" error={errors.district} disabled={selectedCatalog || !exact(values.province, provinceOptions)} onChange={changeDistrict} /><SuggestCombobox id={`${formMode}-subdistrict`} label="ตำบล" value={values.subdistrict} options={subdistrictOptions} placeholder={values.district ? "เลือกตำบล" : "เลือกอำเภอก่อน"} emptyMessage="ไม่พบข้อมูลใน GeoThai" error={errors.subdistrict} disabled={selectedCatalog || !exact(values.district, districtOptions)} onChange={(value) => setField("subdistrict", value)} /></div></section>{values.mode === "catalog" ? <CatalogPicker values={values} results={catalogResults} totalCount={catalogTotal} query={catalogQuery} loading={catalogLoading} selected={selectedCatalog} onQueryChange={setCatalogQuery} onSelect={selectCatalog} onManual={switchManual} /> : <section><h3 className="mb-3 text-sm font-semibold text-slate-900">เพิ่มแบบ Manual</h3><p className="mb-3 text-xs text-amber-700">ใช้โหมด Manual เฉพาะกรณีตรวจสอบแล้วว่าไม่พบหมู่บ้านในฐานข้อมูลอ้างอิง</p><Field label="ชื่อหมู่บ้าน" name="name" value={values.name} placeholder="ชื่อหมู่บ้าน" error={errors.name} onChange={setField} /><div className="mt-3"><TextareaField label="เหตุผล / source note" name="sourceNote" value={values.sourceNote} placeholder="เช่น เพิ่มโดย Super Admin เนื่องจากไม่พบใน Catalog" error={errors.sourceNote} onChange={setField} /></div><button type="button" onClick={() => setValues((current) => ({ ...current, mode: "catalog" }))} className="mt-3 text-sm font-medium text-green-700 hover:underline">กลับไปเลือกจาก Catalog</button></section>}<section><h3 className="mb-3 text-sm font-semibold text-slate-900">ข้อมูลพื้นฐานและข้อมูลเสริม</h3><div className="grid grid-cols-1 gap-3 md:grid-cols-2"><Field label="ชื่อหมู่บ้าน" name="name" value={values.name} placeholder="ชื่อหมู่บ้าน" error={errors.name} readOnly={values.mode === "catalog"} onChange={setField} /><Field label="หมู่ที่" name="moo" value={values.moo} placeholder="หมู่ที่" readOnly={values.mode === "catalog"} onChange={setField} /><Field label="Slug" name="slug" value={values.slug} placeholder="บ้านใหม่ หรือ ban-mai" error={errors.slug} onChange={setField} /><div><label className="mb-1 block text-sm font-medium text-slate-700">สถานะ</label><input value={statusLabel} disabled className="w-full rounded-lg border border-slate-200 bg-slate-50 px-3 py-2 text-sm text-slate-500" /></div></div><div className="mt-3"><TextareaField label="ที่อยู่เพิ่มเติม" name="address" value={values.address} placeholder="ที่อยู่เพิ่มเติมของหมู่บ้าน" onChange={setField} /></div><div className="mt-3 grid grid-cols-1 gap-3 md:grid-cols-3"><Field label="อีเมล" name="email" type="email" value={values.email} placeholder="อีเมล" onChange={setField} /><Field label="เบอร์โทร" name="phone" value={values.phone} placeholder="เบอร์โทร" onChange={setField} /><Field label="เว็บไซต์" name="website" type="url" value={values.website} placeholder="https://example.com" onChange={setField} /></div><div className="mt-3"><TextareaField label="คำอธิบาย" name="description" value={values.description} placeholder="คำอธิบายหมู่บ้าน" onChange={setField} /></div></section></div><div className="sticky bottom-0 -mx-4 mt-6 flex justify-end gap-2 border-t border-slate-200 bg-white px-4 py-3 sm:-mx-6 sm:px-6"><Button type="button" variant="outline" onClick={onClose} disabled={pending}>ยกเลิก</Button><Button type="submit" isLoading={pending}>{formMode === "create" ? "เปิดใช้งานหมู่บ้าน" : "บันทึก"}</Button></div></form></div></div>;
}

function LegacyVillagesToolbar({ geography, initialQuery, initialStatus, initialProvince }: { geography: ThaiProvince[]; initialQuery: string; initialStatus: string; initialProvince: string }) {
  const router = useRouter(); const pathname = usePathname(); const { pushToast } = useToast(); const [query, setQuery] = useState(initialQuery); const [status, setStatus] = useState(initialStatus || "all"); const [province, setProvince] = useState(initialProvince); const [open, setOpen] = useState(false); const [pending, setPending] = useState(false); const [error, setError] = useState("");
  useEffect(() => { setQuery(initialQuery); setStatus(initialStatus || "all"); setProvince(initialProvince); }, [initialProvince, initialQuery, initialStatus]);
  useEffect(() => { const timer = window.setTimeout(() => { const params = new URLSearchParams(); if (query.trim()) params.set("q", query.trim()); if (status !== "all") params.set("status", status); if (province.trim()) params.set("province", province.trim()); router.replace(params.toString() ? `${pathname}?${params}` : pathname); }, 400); return () => window.clearTimeout(timer); }, [pathname, province, query, router, status]);
  const submitSearch = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const params = new URLSearchParams(); if (query.trim()) params.set("q", query.trim()); if (status !== "all") params.set("status", status); if (province.trim()) params.set("province", province.trim()); router.replace(params.toString() ? `${pathname}?${params}` : pathname); };
  return <div className="space-y-4"><div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><h1 className="text-2xl font-bold text-slate-900">จัดการหมู่บ้าน</h1><p className="mt-1 text-sm text-slate-600">ค้นหาและจัดการหมู่บ้านที่เปิดใช้งานในระบบ</p></div><Button type="button" onClick={() => { setError(""); setOpen(true); }} className="gap-2"><Plus className="h-4 w-4" />เพิ่มหมู่บ้าน</Button></div><form onSubmit={submitSearch} className="grid grid-cols-1 gap-3 rounded-lg border border-slate-200 bg-white p-4 shadow-sm md:grid-cols-4"><label className="md:col-span-2"><span className="mb-1 block text-sm font-medium text-slate-700">ค้นหา</span><div className="relative"><Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="ชื่อหมู่บ้าน / slug / ตำบล / อำเภอ / จังหวัด" className="w-full rounded-lg border border-slate-300 py-2 pl-9 pr-3 text-sm placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-green-500" /></div></label><label><span className="mb-1 block text-sm font-medium text-slate-700">สถานะ</span><select value={status} onChange={(event) => setStatus(event.target.value)} className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm"><option value="all">ทุกสถานะ</option><option value="active">เปิดใช้งาน</option><option value="inactive">ปิดใช้งาน</option></select></label><label><span className="mb-1 block text-sm font-medium text-slate-700">จังหวัด</span><select value={province} onChange={(event) => setProvince(event.target.value)} className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm"><option value="">ทุกจังหวัด</option>{geography.map((item) => <option key={item.name} value={item.name}>{item.name}</option>)}</select></label><div className="flex flex-wrap gap-2 md:col-span-4"><Button type="submit" variant="secondary" className="gap-2"><Search className="h-4 w-4" />ค้นหา</Button><Link href="/superadmin/villages" className="inline-flex items-center rounded-lg border border-slate-300 px-4 py-2 text-sm font-medium text-slate-700 hover:bg-slate-50">ล้างตัวกรอง</Link></div></form>{open ? <VillageFormModal formMode="create" title="เพิ่มหมู่บ้านใหม่" geography={geography} initialValues={emptyForm} statusLabel="เปิดใช้งาน" pending={pending} serverError={error} onClose={() => !pending && setOpen(false)} onSubmit={async (values) => { setPending(true); setError(""); try { const data = new FormData(); Object.entries(values).forEach(([key, value]) => data.set(key, value)); await createVillageAction(data); pushToast({ tone: "success", title: "เปิดใช้งานหมู่บ้านสำเร็จ", description: values.name }); setOpen(false); router.refresh(); } catch (cause) { const message = cause instanceof Error ? cause.message : "เกิดข้อผิดพลาด"; setError(message); pushToast({ tone: "error", title: "สร้างหมู่บ้านไม่สำเร็จ", description: message }); } finally { setPending(false); } }} /> : null}</div>;
}

function VillageFormModal({ formMode, title, geography, initialValues, statusLabel, pending, serverError, onClose, onSubmit }: { formMode: "create" | "edit"; title: string; geography: ThaiProvince[]; initialValues: FormValues; statusLabel: string; pending: boolean; serverError?: string; onClose: () => void; onSubmit: (values: FormValues) => Promise<void> }) {
  const [values, setValues] = useState(initialValues);
  const [errors, setErrors] = useState<FieldErrors>({});
  const [catalogQuery, setCatalogQuery] = useState("");
  const [catalogResults, setCatalogResults] = useState<CatalogResult[]>([]);
  const [catalogTotal, setCatalogTotal] = useState(0);
  const [catalogLoading, setCatalogLoading] = useState(false);
  const isCatalogEdit = formMode === "edit" && Boolean(initialValues.catalogVillageId);
  const isManualEdit = formMode === "edit" && !isCatalogEdit;
  const provinceOptions = useMemo(() => options(geography.map((item) => item.name)), [geography]);
  const province = geography.find((item) => item.name === values.province);
  const districtOptions = useMemo(() => options(province?.districts.map((item) => item.name) ?? []), [province]);
  const district = province?.districts.find((item) => item.name === values.district);
  const subdistrictOptions = useMemo(() => options(district?.subdistricts ?? []), [district]);
  const selectedCatalog = values.mode === "catalog" && Boolean(values.catalogVillageId || values.builtInCatalogId);
  const setField = (name: keyof FormValues, value: string) => { setValues((current) => ({ ...current, [name]: value })); setErrors((current) => ({ ...current, [name]: undefined })); };
  const changeProvince = (province: string) => setValues((current) => ({ ...current, province, district: "", subdistrict: "", catalogVillageId: "", builtInCatalogId: "" }));
  const changeDistrict = (district: string) => setValues((current) => ({ ...current, district, subdistrict: "", catalogVillageId: "", builtInCatalogId: "" }));

  useEffect(() => { if (formMode !== "create" || values.mode !== "catalog" || !values.province || !values.district || !values.subdistrict) return; let cancelled = false; const timer = window.setTimeout(() => { setCatalogLoading(true); void searchVillageCatalogAction({ province: values.province, district: values.district, subdistrict: values.subdistrict, query: catalogQuery }).then((result) => { if (!cancelled) { setCatalogResults(result.items); setCatalogTotal(result.totalCount); setValues((current) => ({ ...current, catalogSource: result.source })); } }).finally(() => { if (!cancelled) setCatalogLoading(false); }); }, 250); return () => { cancelled = true; window.clearTimeout(timer); }; }, [catalogQuery, formMode, values.district, values.mode, values.province, values.subdistrict]);
  const selectCatalog = (item: CatalogResult) => { if (item.village) return; setValues((current) => ({ ...current, mode: "catalog", catalogVillageId: item.source === "DATABASE" ? item.id : "", catalogSource: item.source, builtInCatalogId: item.source === "BUILT_IN_DEMO" ? item.id : "", name: item.villageName, moo: item.moo ?? "", slug: buildCatalogVillageSlug({ villageName: item.villageName, moo: item.moo, officialCode: item.officialCode, fallbackId: item.id }), province: item.province, district: item.district, subdistrict: item.subdistrict })); };
  const identityChanged = isManualEdit && ["name", "moo", "province", "district", "subdistrict"].some((key) => values[key as keyof FormValues] !== initialValues[key as keyof FormValues]);
  const validate = () => { const next: FieldErrors = {}; if (!isCatalogEdit) { if (!exact(values.province, provinceOptions)) next.province = "กรุณาเลือกจังหวัดจากรายการ"; if (!exact(values.district, districtOptions)) next.district = "กรุณาเลือกอำเภอจากรายการ"; if (!exact(values.subdistrict, subdistrictOptions)) next.subdistrict = "กรุณาเลือกตำบลจากรายการ"; } if (formMode === "create" && values.mode === "catalog" && !values.catalogVillageId && !values.builtInCatalogId) next.catalogVillageId = "กรุณาเลือกหมู่บ้านจากรายการ"; if ((values.mode === "manual" || isManualEdit) && !values.name.trim()) next.name = "กรุณากรอกชื่อหมู่บ้าน"; if ((values.mode === "manual" || isManualEdit) && !values.moo.trim()) next.moo = "กรุณาระบุหมู่ที่"; if (formMode === "create" && values.mode === "manual" && !values.sourceNote.trim()) next.sourceNote = "กรุณาระบุที่มา"; if (identityChanged && !values.correctionReason.trim()) next.correctionReason = "กรุณาระบุเหตุผลสำหรับการแก้ไขข้อมูลอ้างอิง"; if (values.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/u.test(values.email)) next.email = "รูปแบบอีเมลไม่ถูกต้อง"; if (values.website) { try { new URL(values.website); } catch { next.website = "รูปแบบเว็บไซต์ไม่ถูกต้อง"; } } setErrors(next); return Object.keys(next).length === 0; };
  const submit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (!pending && validate()) await onSubmit(values); };

  return <div className="fixed inset-0 z-[80] flex items-end justify-center bg-slate-950/50 sm:items-center sm:p-4" role="dialog" aria-modal="true"><div className="flex max-h-[92vh] w-full flex-col rounded-t-2xl bg-white shadow-2xl sm:max-w-3xl sm:rounded-2xl"><div className="flex items-center justify-between border-b border-slate-200 px-4 py-3 sm:px-6"><div><h2 className="text-lg font-semibold text-slate-900">{title}</h2>{serverError ? <p className="mt-1 text-sm text-red-600">{serverError}</p> : null}</div><button type="button" onClick={onClose} disabled={pending} aria-label="ปิด" className="rounded-full p-2 text-slate-500 hover:bg-slate-100"><X className="h-5 w-5" /></button></div><form onSubmit={submit} className="overflow-y-auto px-4 py-4 sm:px-6"><div className="space-y-5">
    {isCatalogEdit ? <section className="rounded-xl border border-slate-200 bg-slate-50 p-4"><h3 className="font-semibold text-slate-900">ข้อมูลหมู่บ้าน</h3><p className="mt-2 text-sm text-slate-800">{values.name} · หมู่ {values.moo || "-"}</p><p className="mt-1 text-sm text-slate-600">ต.{values.subdistrict || "-"} · อ.{values.district || "-"} · จ.{values.province || "-"}</p><p className="mt-3 text-xs font-medium text-slate-500">แหล่งข้อมูล: ฐานข้อมูลหมู่บ้านอ้างอิง</p><p className="mt-2 text-xs text-slate-500">ข้อมูลชื่อและพื้นที่อ้างอิงไม่สามารถเปลี่ยนจากหน้านี้ได้</p></section> : <><section><p className="mb-3 text-xs text-slate-500">{formMode === "create" ? "1. เลือกพื้นที่  2. เลือกหมู่บ้านอ้างอิงหรือเพิ่มแบบ Manual" : "ข้อมูลอ้างอิงของหมู่บ้านแบบ Manual"}</p><div className="grid grid-cols-1 gap-3 md:grid-cols-3"><SuggestCombobox id={`${formMode}-province`} label="จังหวัด" value={values.province} options={provinceOptions} placeholder="เลือกจังหวัด" emptyMessage="ไม่พบข้อมูล" error={errors.province} onChange={changeProvince} /><SuggestCombobox id={`${formMode}-district`} label="อำเภอ" value={values.district} options={districtOptions} placeholder="เลือกอำเภอ" emptyMessage="ไม่พบข้อมูล" error={errors.district} disabled={!exact(values.province, provinceOptions)} onChange={changeDistrict} /><SuggestCombobox id={`${formMode}-subdistrict`} label="ตำบล" value={values.subdistrict} options={subdistrictOptions} placeholder="เลือกตำบล" emptyMessage="ไม่พบข้อมูล" error={errors.subdistrict} disabled={!exact(values.district, districtOptions)} onChange={(value) => setField("subdistrict", value)} /></div></section>{formMode === "create" && values.mode === "catalog" ? <CatalogPicker values={values} results={catalogResults} totalCount={catalogTotal} query={catalogQuery} loading={catalogLoading} selected={selectedCatalog} onQueryChange={setCatalogQuery} onSelect={selectCatalog} onManual={() => setValues((current) => ({ ...current, mode: "manual", catalogVillageId: "", builtInCatalogId: "" }))} /> : null}<section className="grid grid-cols-1 gap-3 md:grid-cols-2"><Field label="ชื่อหมู่บ้าน" name="name" value={values.name} placeholder="ชื่อหมู่บ้าน" error={errors.name} onChange={setField} readOnly={formMode === "create" && values.mode === "catalog"} /><Field label="หมู่ที่" name="moo" value={values.moo} placeholder="หมู่ที่" error={errors.moo} onChange={setField} readOnly={formMode === "create" && values.mode === "catalog"} /></section>{formMode === "create" && values.mode === "manual" ? <TextareaField label="ที่มาเพิ่มเติม" name="sourceNote" value={values.sourceNote} placeholder="เหตุผลที่เพิ่มแบบ Manual" error={errors.sourceNote} onChange={setField} /> : null}{identityChanged ? <TextareaField label="เหตุผลสำหรับการแก้ไขข้อมูลอ้างอิง" name="correctionReason" value={values.correctionReason} placeholder="เช่น แก้ไขพื้นที่ที่กรอกผิดตอนเพิ่มแบบ Manual" error={errors.correctionReason} onChange={setField} /> : null}</>}
    <section><h3 className="mb-3 text-sm font-semibold text-slate-900">ข้อมูลเพิ่มเติม</h3><TextareaField label="ที่อยู่เพิ่มเติม" name="address" value={values.address} placeholder="ที่อยู่เพิ่มเติมของหมู่บ้าน" onChange={setField} /><div className="mt-3 grid grid-cols-1 gap-3 md:grid-cols-3"><Field label="เบอร์โทร" name="phone" value={values.phone} placeholder="เบอร์โทร" onChange={setField} /><Field label="อีเมล" name="email" type="email" value={values.email} placeholder="อีเมล" error={errors.email} onChange={setField} /><Field label="เว็บไซต์" name="website" type="url" value={values.website} placeholder="https://example.com" error={errors.website} onChange={setField} /></div><div className="mt-3"><TextareaField label="คำอธิบาย" name="description" value={values.description} placeholder="คำอธิบายหมู่บ้าน" onChange={setField} /></div>{isManualEdit ? <div className="mt-3"><TextareaField label="ที่มาเพิ่มเติม" name="sourceNote" value={values.sourceNote} placeholder="ที่มาเพิ่มเติม" onChange={setField} /></div> : null}</section>
  </div><div className="sticky bottom-0 -mx-4 mt-6 flex justify-end gap-2 border-t border-slate-200 bg-white px-4 py-3 sm:-mx-6 sm:px-6"><Button type="button" variant="outline" onClick={onClose} disabled={pending}>ยกเลิก</Button><Button type="submit" isLoading={pending}>{formMode === "create" ? "เปิดใช้งานหมู่บ้าน" : "บันทึก"}</Button></div></form></div></div>;
}

export function VillagesToolbar({ geography, initialQuery, initialStatus, initialProvince, initialAttention }: { geography: ThaiProvince[]; initialQuery: string; initialStatus: string; initialProvince: string; initialAttention: string }) {
  const router = useRouter();
  const pathname = usePathname();
  const { pushToast } = useToast();
  const [query, setQuery] = useState(initialQuery);
  const [status, setStatus] = useState(initialStatus || "all");
  const [province, setProvince] = useState(initialProvince);
  const [open, setOpen] = useState(false);
  const [pending, setPending] = useState(false);
  const [error, setError] = useState("");
  const { setAction } = useSuperAdminPageHeader();
  const provinceOptions = useMemo(() => options(geography.map((item) => item.name)), [geography]);

  useEffect(() => { setQuery(initialQuery); setStatus(initialStatus || "all"); setProvince(initialProvince); }, [initialProvince, initialQuery, initialStatus]);
  useEffect(() => { const action = { label: "เพิ่มหมู่บ้าน", onClick: () => { setError(""); setOpen(true); } }; setAction(action); return () => setAction(null); }, [setAction]);

  const submitSearch = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const params = new URLSearchParams();
    params.set("searched", "1");
    if (query.trim()) params.set("q", query.trim());
    if (status !== "all") params.set("status", status);
    if (province.trim()) params.set("province", province.trim());
    if (initialAttention) params.set("attention", initialAttention);
    router.replace(params.toString() ? `${pathname}?${params}` : pathname);
  };

  return <>
    <form onSubmit={submitSearch} className="sticky top-[var(--app-sticky-top,4rem)] z-30 -mx-4 flex w-[calc(100%+2rem)] flex-wrap items-end gap-2 border-y border-slate-200 bg-white/95 px-3 py-1.5 backdrop-blur supports-[backdrop-filter]:bg-white/90 sm:-mx-6 sm:w-[calc(100%+3rem)] sm:px-6">
      {initialAttention ? <div className="flex w-full items-center gap-2 text-xs text-slate-500 sm:order-last sm:w-auto sm:grow"><span className="rounded-full border border-amber-200 bg-amber-50 px-2 py-1 font-medium text-amber-800">มุมมอง: {attentionLabels[initialAttention] ?? initialAttention}</span></div> : null}
      <label className="min-w-[min(100%,18rem)] flex-1 sm:min-w-[22rem]"><span className="sr-only">ค้นหา</span><div className="relative"><Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="ค้นหาชื่อหมู่บ้าน จังหวัด อำเภอ หรือตำบล" aria-label="ค้นหาหมู่บ้าน" className="h-9 w-full rounded-md border border-slate-300 py-1.5 pl-9 pr-3 text-sm placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-green-500" /></div></label>
      <label className="w-full sm:w-40"><span className="sr-only">สถานะ</span><select aria-label="สถานะ" value={status} onChange={(event) => setStatus(event.target.value)} className="h-9 w-full rounded-md border border-slate-300 bg-white px-2.5 text-sm text-slate-700 focus:outline-none focus:ring-2 focus:ring-green-500"><option value="all">ทุกสถานะ</option><option value="active">เปิดใช้งาน</option><option value="inactive">ปิดใช้งาน</option></select></label>
      <div className="w-full sm:w-56"><SuggestCombobox id="village-filter-province" label="จังหวัด" labelClassName="sr-only" value={province} options={provinceOptions} placeholder="เลือกจังหวัด" emptyMessage="ไม่พบจังหวัด" inputClassName="h-9 border-slate-300 focus:ring-green-500" onChange={setProvince} /></div>
      <div className="flex w-full gap-2 sm:w-auto"><Button type="submit" size="sm" variant="secondary" className="gap-1.5"><Search className="h-4 w-4" />ค้นหา</Button><Link href="/superadmin/villages" className="inline-flex h-9 items-center rounded-md px-2.5 text-sm font-medium text-slate-500 transition hover:bg-slate-50 hover:text-slate-800 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-green-500 focus-visible:ring-offset-2">รีเซ็ต</Link></div>
    </form>
    {open ? <VillageFormModal formMode="create" title="เพิ่มหมู่บ้านใหม่" geography={geography} initialValues={emptyForm} statusLabel="เปิดใช้งาน" pending={pending} serverError={error} onClose={() => !pending && setOpen(false)} onSubmit={async (values) => { setPending(true); setError(""); try { const data = new FormData(); Object.entries(values).forEach(([key, value]) => data.set(key, value)); await createVillageAction(data); pushToast({ tone: "success", title: "เปิดใช้งานหมู่บ้านสำเร็จ", description: values.name }); setOpen(false); router.refresh(); } catch (cause) { const message = cause instanceof Error ? cause.message : "เกิดข้อผิดพลาด"; setError(message); pushToast({ tone: "error", title: "สร้างหมู่บ้านไม่สำเร็จ", description: message }); } finally { setPending(false); } }} /> : null}
  </>;
}

function toForm(village: VillageRow): FormValues { return { mode: village.catalogVillageId ? "catalog" : "manual", catalogVillageId: village.catalogVillageId ?? "", catalogSource: "DATABASE", builtInCatalogId: "", name: village.name, moo: village.moo ?? "", slug: village.slug, province: village.province ?? "", district: village.district ?? "", subdistrict: village.subdistrict ?? "", address: village.address ?? "", phone: village.phone ?? "", email: village.email ?? "", website: village.website ?? "", description: village.description ?? "", sourceNote: village.sourceNote ?? "", correctionReason: "" }; }
function Detail({ label, value, fallback }: { label: string; value: string | null; fallback: string }) { return <div><p className="text-xs font-medium text-slate-500">{label}</p><p className={`mt-0.5 text-sm ${value?.trim() ? "text-slate-800" : "text-muted-foreground"}`}>{displayValue(value, fallback)}</p></div>; }

export function VillageCard({ village, geography }: { village: VillageRow; geography: ThaiProvince[] }) {
  const router = useRouter(); const { pushToast } = useToast(); const [pending, setPending] = useState(false); const [editOpen, setEditOpen] = useState(false); const [error, setError] = useState(""); const [dialog, setDialog] = useState<DialogState>(null);
  const run = async (work: () => Promise<void>, title: string) => { setPending(true); try { await work(); pushToast({ tone: "success", title, description: village.name }); router.refresh(); } catch (cause) { pushToast({ tone: "error", title: "ดำเนินการไม่สำเร็จ", description: cause instanceof Error ? cause.message : "เกิดข้อผิดพลาด" }); } finally { setPending(false); setDialog(null); } };
  const location = [village.subdistrict && `ต.${village.subdistrict}`, village.district && `อ.${village.district}`, village.province && `จ.${village.province}`].filter(Boolean) as string[];
  const contacts = [["อีเมล", village.email], ["เบอร์โทร", village.phone], ["เว็บไซต์", village.website], ["ที่อยู่", village.address]].filter(([, value]) => value?.trim()) as [string, string][];
  return <article className="rounded-lg border border-slate-200 bg-white p-4 shadow-sm"><div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div className="min-w-0"><Link href={`/superadmin/villages/${village.id}`} className="break-words text-lg font-semibold text-slate-900 hover:text-green-700 hover:underline">{village.name}</Link><p className="mt-1 flex flex-wrap gap-x-2 text-sm text-slate-600">{village.moo ? <span>หมู่ที่ {village.moo}</span> : null}{location.map((part) => <span key={part}>{part}</span>)}</p><p className="mt-1 truncate text-xs text-slate-400" title={`/${village.slug}`}>/{village.slug}</p></div><div className="flex shrink-0 flex-wrap gap-1.5"><span className={`rounded-full px-2 py-1 text-xs font-semibold ${village.isActive ? "bg-emerald-100 text-emerald-700" : "bg-slate-200 text-slate-700"}`}>{village.isActive ? "เปิดใช้งาน" : "ปิดใช้งาน"}</span><span title={village.catalogVillageId ? "ข้อมูลหมู่บ้านอ้างอิงจากฐานข้อมูล" : "ข้อมูลที่เพิ่มโดยผู้ดูแลระบบ"} className={`inline-flex items-center gap-1 rounded-full border px-2 py-1 text-xs font-medium ${village.catalogVillageId ? "border-sky-200 bg-sky-50 text-sky-800" : "border-violet-200 bg-violet-50 text-violet-800"}`}>{village.catalogVillageId ? <Database className="h-3.5 w-3.5" aria-hidden="true" /> : <UserRoundPlus className="h-3.5 w-3.5" aria-hidden="true" />}{village.catalogVillageId ? "ฐานข้อมูลอ้างอิง" : "เพิ่มโดยผู้ดูแลระบบ"}</span></div></div>{contacts.length ? <div className="mt-3 flex flex-wrap gap-x-4 gap-y-1 text-xs text-slate-600">{contacts.map(([label, value]) => <span key={label} className="max-w-full truncate"><span className="text-slate-400">{label} </span>{value}</span>)}</div> : null}{village.sourceNote ? <p className="mt-2 truncate text-xs text-slate-400" title={village.sourceNote}>ที่มาเพิ่มเติม: {village.sourceNote}</p> : null}<div className="mt-4 flex flex-wrap items-center gap-2 border-t border-slate-100 pt-3"><Link href={`/superadmin/villages/${village.id}`} className="inline-flex min-h-9 items-center gap-2 rounded-lg bg-slate-900 px-3 py-1.5 text-sm font-medium text-white hover:bg-slate-800"><ExternalLink className="h-4 w-4" />เข้า Workspace</Link><Button type="button" size="sm" variant="outline" className="gap-1.5" onClick={() => { setError(""); setEditOpen(true); }}><Pencil className="h-4 w-4" />แก้ไข</Button><Button type="button" size="sm" variant="ghost" className="gap-1.5 text-slate-500" title={village.isActive ? "ปิดใช้งานหมู่บ้าน" : "เปิดใช้งานหมู่บ้าน"} aria-label={village.isActive ? "ปิดใช้งานหมู่บ้าน" : "เปิดใช้งานหมู่บ้าน"} onClick={() => setDialog({ title: village.isActive ? "ยืนยันปิดการใช้งานหมู่บ้าน" : "ยืนยันเปิดการใช้งานหมู่บ้าน", description: `${village.isActive ? "ปิด" : "เปิด"}การใช้งาน ${village.name}`, tone: "default", action: async () => { const data = new FormData(); data.set("id", village.id); data.set("nextActive", String(!village.isActive)); await run(() => toggleVillageActiveAction(data), village.isActive ? "ปิดการใช้งานแล้ว" : "เปิดการใช้งานแล้ว"); } })}><Power className="h-4 w-4" /><span className="hidden sm:inline">{village.isActive ? "ปิดใช้งาน" : "เปิดใช้งาน"}</span></Button><span className="ml-auto text-xs text-slate-500">สมาชิก {village.counts.memberships} · บ้าน {village.counts.houses}</span></div>{editOpen ? <VillageFormModal formMode="edit" title="แก้ไขหมู่บ้าน" geography={geography} initialValues={toForm(village)} statusLabel={village.isActive ? "เปิดใช้งาน" : "ปิดใช้งาน"} pending={pending} serverError={error} onClose={() => !pending && setEditOpen(false)} onSubmit={async (values) => { setPending(true); setError(""); try { const data = new FormData(); data.set("id", village.id); Object.entries(values).forEach(([key, value]) => data.set(key, value)); await updateVillageAction(data); pushToast({ tone: "success", title: "บันทึกข้อมูลแล้ว", description: village.name }); setEditOpen(false); router.refresh(); } catch (cause) { const message = cause instanceof Error ? cause.message : "เกิดข้อผิดพลาด"; setError(message); pushToast({ tone: "error", title: "บันทึกไม่สำเร็จ", description: message }); } finally { setPending(false); } }} /> : null}<ConfirmDialog open={Boolean(dialog)} title={dialog?.title ?? ""} description={dialog?.description} tone={dialog?.tone} pending={pending} onClose={() => !pending && setDialog(null)} onConfirm={() => { void dialog?.action(); }} /></article>;
}

function VillageCardLegacy({ village, geography }: { village: VillageRow; geography: ThaiProvince[] }) {
  const router = useRouter(); const { pushToast } = useToast(); const [pending, setPending] = useState(false); const [editOpen, setEditOpen] = useState(false); const [error, setError] = useState(""); const [dialog, setDialog] = useState<DialogState>(null);
  const run = async (work: () => Promise<void>, title: string) => { setPending(true); try { await work(); pushToast({ tone: "success", title, description: village.name }); router.refresh(); } catch (cause) { pushToast({ tone: "error", title: "ดำเนินการไม่สำเร็จ", description: cause instanceof Error ? cause.message : "เกิดข้อผิดพลาด" }); } finally { setPending(false); setDialog(null); } };
  const location = [village.subdistrict ? `ต.${village.subdistrict}` : "ยังไม่มีข้อมูลตำบล", village.district ? `อ.${village.district}` : "ยังไม่มีข้อมูลอำเภอ", village.province ? `จ.${village.province}` : "ยังไม่มีข้อมูลจังหวัด"];
  return <article className="rounded-lg border border-slate-200 bg-white p-4 shadow-sm"><div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><Link href={`/superadmin/villages/${village.id}`} className="text-lg font-semibold text-slate-900 hover:text-green-700 hover:underline">{village.name}</Link><p className="mt-1 flex flex-wrap gap-x-2 text-sm text-slate-600">{location.map((part) => <span key={part} className={part.startsWith("ยังไม่มี") ? "text-muted-foreground" : ""}>{part}</span>)}</p><p className="mt-1 text-xs text-slate-500">/{village.slug}{village.moo ? ` · หมู่ที่ ${village.moo}` : ""}</p></div><div className="flex flex-wrap gap-2"><span className={`rounded-full px-2 py-1 text-xs font-semibold ${village.isActive ? "bg-emerald-100 text-emerald-700" : "bg-slate-200 text-slate-700"}`}>{village.isActive ? "เปิดใช้งาน" : "ปิดใช้งาน"}</span><span className="rounded-full bg-slate-100 px-2 py-1 text-xs text-slate-600">{village.catalogVillageId ? "จากฐานข้อมูลหมู่บ้านอ้างอิง" : "เพิ่มเองโดยผู้ดูแลระบบ"}</span></div></div><div className="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Detail label="อีเมล" value={village.email} fallback="ยังไม่มีอีเมล" /><Detail label="เบอร์โทร" value={village.phone} fallback="ยังไม่มีเบอร์โทร" /><Detail label="เว็บไซต์" value={village.website} fallback="ยังไม่มีเว็บไซต์" /><Detail label="ที่อยู่" value={village.address} fallback="ยังไม่มีที่อยู่" /></div>{village.sourceNote ? <p className="mt-3 text-xs text-muted-foreground">ที่มาเพิ่มเติม: {village.sourceNote}</p> : null}<div className="mt-4 flex flex-wrap items-center gap-2 border-t border-slate-100 pt-3"><Link href={`/superadmin/villages/${village.id}`} className="inline-flex items-center gap-2 rounded-lg bg-slate-900 px-3 py-2 text-sm font-medium text-white"><ExternalLink className="h-4 w-4" />เข้า Workspace</Link><Button type="button" variant="outline" className="gap-2" onClick={() => { setError(""); setEditOpen(true); }}><Pencil className="h-4 w-4" />แก้ไข</Button><Button type="button" variant="outline" onClick={() => setDialog({ title: village.isActive ? "ยืนยันปิดการใช้งานหมู่บ้าน" : "ยืนยันเปิดการใช้งานหมู่บ้าน", description: `${village.isActive ? "ปิด" : "เปิด"}การใช้งาน ${village.name}`, tone: "default", action: async () => { const data = new FormData(); data.set("id", village.id); data.set("nextActive", String(!village.isActive)); await run(() => toggleVillageActiveAction(data), village.isActive ? "ปิดการใช้งานแล้ว" : "เปิดการใช้งานแล้ว"); } })}>{village.isActive ? "ปิดใช้งาน" : "เปิดใช้งาน"}</Button><Button type="button" variant="danger" onClick={() => setDialog({ title: "ยืนยันลบหมู่บ้าน", description: `การลบ ${village.name} ไม่สามารถย้อนกลับได้`, tone: "danger", action: async () => { const data = new FormData(); data.set("id", village.id); await run(() => deleteVillageAction(data), "ลบหมู่บ้านแล้ว"); } })}>ลบ</Button><span className="ml-auto text-xs text-slate-500">สมาชิก {village.counts.memberships} · บ้าน {village.counts.houses} · ข่าว {village.counts.news}</span></div>{editOpen ? <VillageFormModal formMode="edit" title="แก้ไขหมู่บ้าน" geography={geography} initialValues={toForm(village)} statusLabel={village.isActive ? "เปิดใช้งาน" : "ปิดใช้งาน"} pending={pending} serverError={error} onClose={() => !pending && setEditOpen(false)} onSubmit={async (values) => { setPending(true); setError(""); try { const data = new FormData(); data.set("id", village.id); Object.entries(values).forEach(([key, value]) => data.set(key, value)); await updateVillageAction(data); pushToast({ tone: "success", title: "บันทึกข้อมูลแล้ว", description: village.name }); setEditOpen(false); router.refresh(); } catch (cause) { const message = cause instanceof Error ? cause.message : "เกิดข้อผิดพลาด"; setError(message); pushToast({ tone: "error", title: "บันทึกไม่สำเร็จ", description: message }); } finally { setPending(false); } }} /> : null}<ConfirmDialog open={Boolean(dialog)} title={dialog?.title ?? ""} description={dialog?.description} tone={dialog?.tone} pending={pending} onClose={() => !pending && setDialog(null)} onConfirm={() => { void dialog?.action(); }} /></article>;
}
